import { Pool, neonConfig } from '@neondatabase/serverless';
import { drizzle } from 'drizzle-orm/neon-serverless';
import ws from "ws";
import * as schema from "@shared/schema";

neonConfig.webSocketConstructor = ws;

if (!process.env.DATABASE_URL) {
  throw new Error(
    "DATABASE_URL must be set. Did you forget to provision a database?",
  );
}

export const pool = new Pool({ connectionString: process.env.DATABASE_URL });
export const db = drizzle({ client: pool, schema });

server/index.ts.content:
import express, { type Request, Response, NextFunction } from "express";
import { registerRoutes } from "./routes";
import { setupVite, serveStatic, log } from "./vite";
import { seedDatabase } from "./seed-data";

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  const server = await registerRoutes(app);

  // Seed database in background after server starts (non-blocking)
  setImmediate(async () => {
    try {
      await seedDatabase();
    } catch (error) {
      console.error("Error seeding database:", error);
    }
  });

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    res.status(status).json({ message });
    throw err;
  });

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // ALWAYS serve the app on the port specified in the environment variable PORT
  // Other ports are firewalled. Default to 5000 if not specified.
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = parseInt(process.env.PORT || '5000', 10);
  server.listen({
    port,
    host: '0.0.0.0', // Important for deployment - allows external connections
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

server/replitAuth.ts.content:
import * as client from "openid-client";
import { Strategy, type VerifyFunction } from "openid-client/passport";

import passport from "passport";
import session from "express-session";
import type { Express, RequestHandler } from "express";
import memoize from "memoizee";
import connectPg from "connect-pg-simple";
import { storage } from "./storage";

if (!process.env.REPLIT_DOMAINS) {
  throw new Error("Environment variable REPLIT_DOMAINS not provided");
}

const getOidcConfig = memoize(
  async () => {
    return await client.discovery(
      new URL(process.env.ISSUER_URL ?? "https://replit.com/oidc"),
      process.env.REPL_ID!
    );
  },
  { maxAge: 3600 * 1000 }
);

export function getSession() {
  const sessionTtl = 7 * 24 * 60 * 60 * 1000; // 1 week
  const pgStore = connectPg(session);
  const sessionStore = new pgStore({
    conString: process.env.DATABASE_URL,
    createTableIfMissing: false,
    ttl: sessionTtl,
    tableName: "sessions",
  });
  return session({
    secret: process.env.SESSION_SECRET!,
    store: sessionStore,
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      secure: true,
      maxAge: sessionTtl,
    },
  });
}

function updateUserSession(
  user: any,
  tokens: client.TokenEndpointResponse & client.TokenEndpointResponseHelpers
) {
  user.claims = tokens.claims();
  user.access_token = tokens.access_token;
  user.refresh_token = tokens.refresh_token;
  user.expires_at = user.claims?.exp;
}

async function upsertUser(
  claims: any,
) {
  // Set role based on email - jhustle44@gmail.com gets admin privileges
  const role = claims["email"] === "jhustle44@gmail.com" ? "admin" : "user";

  await storage.upsertUser({
    id: claims["sub"],
    email: claims["email"],
    firstName: claims["first_name"],
    lastName: claims["last_name"],
    profileImageUrl: claims["profile_image_url"],
    role: role,
  });
}

export async function setupAuth(app: Express) {
  app.set("trust proxy", 1);
  app.use(getSession());
  app.use(passport.initialize());
  app.use(passport.session());

  const config = await getOidcConfig();

  const verify: VerifyFunction = async (
    tokens: client.TokenEndpointResponse & client.TokenEndpointResponseHelpers,
    verified: passport.AuthenticateCallback
  ) => {
    const user = {};
    updateUserSession(user, tokens);
    await upsertUser(tokens.claims());
    verified(null, user);
  };

  for (const domain of process.env
    .REPLIT_DOMAINS!.split(",")) {
    const strategy = new Strategy(
      {
        name: `replitauth:${domain}`,
        config,
        scope: "openid email profile offline_access",
        callbackURL: `https://${domain}/api/callback`,
      },
      verify,
    );
    passport.use(strategy);
  }

  passport.serializeUser((user: Express.User, cb) => cb(null, user));
  passport.deserializeUser((user: Express.User, cb) => cb(null, user));

  app.get("/api/login", (req, res, next) => {
    passport.authenticate(`replitauth:${req.hostname}`, {
      prompt: "login consent",
      scope: ["openid", "email", "profile", "offline_access"],
    })(req, res, next);
  });

  app.get("/api/callback", (req, res, next) => {
    passport.authenticate(`replitauth:${req.hostname}`, {
      successReturnToOrRedirect: "/",
      failureRedirect: "/api/login",
    })(req, res, next);
  });

  app.get("/api/logout", (req, res) => {
    req.logout(() => {
      res.redirect(
        client.buildEndSessionUrl(config, {
          client_id: process.env.REPL_ID!,
          post_logout_redirect_uri: `${req.protocol}://${req.hostname}`,
        }).href
      );
    });
  });
}

export const isAuthenticated: RequestHandler = async (req, res, next) => {
  const user = req.user as any;

  if (!req.isAuthenticated() || !user.expires_at) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const now = Math.floor(Date.now() / 1000);
  if (now <= user.expires_at) {
    return next();
  }

  const refreshToken = user.refresh_token;
  if (!refreshToken) {
    res.status(401).json({ message: "Unauthorized" });
    return;
  }

  try {
    const config = await getOidcConfig();
    const tokenResponse = await client.refreshTokenGrant(config, refreshToken);
    updateUserSession(user, tokenResponse);
    return next();
  } catch (error) {
    res.status(401).json({ message: "Unauthorized" });
    return;
  }
};

server/routes.ts.content:
import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { insertRepairGuideSchema, insertTroubleshootingFlowSchema, insertDeviceComponentSchema, insertFavoriteSchema } from "@shared/schema";
import { setupAuth, isAuthenticated } from "./replitAuth";
import { requireAdmin } from "./middleware/adminAuth";

export async function registerRoutes(app: Express): Promise<Server> {
  // Auth middleware
  await setupAuth(app);

  // Auth routes
  app.get('/api/auth/user', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      res.json(user);
    } catch (error) {
      console.error("Error fetching user:", error);
      res.status(500).json({ message: "Failed to fetch user" });
    }
  });

  // Favorites routes
  app.get('/api/favorites', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const favorites = await storage.getUserFavorites(userId);
      res.json(favorites);
    } catch (error) {
      console.error("Error fetching favorites:", error);
      res.status(500).json({ message: "Failed to fetch favorites" });
    }
  });

  app.post('/api/favorites', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const favoriteData = insertFavoriteSchema.parse(req.body);
      const favorite = await storage.addToFavorites(userId, favoriteData);
      res.json(favorite);
    } catch (error) {
      console.error("Error adding favorite:", error);
      res.status(500).json({ message: "Failed to add favorite" });
    }
  });

  app.delete('/api/favorites/:itemId/:itemType', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const { itemId, itemType } = req.params;
      await storage.removeFromFavorites(userId, itemId, itemType);
      res.json({ success: true });
    } catch (error) {
      console.error("Error removing favorite:", error);
      res.status(500).json({ message: "Failed to remove favorite" });
    }
  });

  app.get('/api/favorites/check/:itemId/:itemType', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const { itemId, itemType } = req.params;
      const isFavorited = await storage.isFavorited(userId, itemId, itemType);
      res.json({ isFavorited });
    } catch (error) {
      console.error("Error checking favorite:", error);
      res.status(500).json({ message: "Failed to check favorite status" });
    }
  });
  // Repair Guides
  app.get("/api/repair-guides", async (req, res) => {
    try {
      const { deviceType, category, difficulty } = req.query;
      const guides = await storage.getRepairGuides({
        deviceType: deviceType as string,
        category: category as string,
        difficulty: difficulty as string,
      });
      res.json(guides);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch repair guides" });
    }
  });

  app.get("/api/repair-guides/search", async (req, res) => {
    try {
      const { q } = req.query;
      if (!q || typeof q !== "string") {
        return res.status(400).json({ message: "Search query is required" });
      }
      const guides = await storage.searchRepairGuides(q);
      res.json(guides);
    } catch (error) {
      res.status(500).json({ message: "Failed to search repair guides" });
    }
  });

  app.get("/api/repair-guides/:id", async (req, res) => {
    try {
      const guide = await storage.getRepairGuide(req.params.id);
      if (!guide) {
        return res.status(404).json({ message: "Repair guide not found" });
      }
      // Increment view count when guide is viewed
      await storage.updateViewCount(req.params.id);
      res.json(guide);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch repair guide" });
    }
  });

  app.post("/api/repair-guides", async (req, res) => {
    try {
      const validatedData = insertRepairGuideSchema.parse(req.body);
      const guide = await storage.createRepairGuide(validatedData);
      res.status(201).json(guide);
    } catch (error) {
      res.status(400).json({ message: "Invalid repair guide data" });
    }
  });

  // User-created guides endpoint
  app.post("/api/user-guides", async (req, res) => {
    try {
      const validatedData = insertRepairGuideSchema.parse(req.body);
      const guide = await storage.createUserGuide(validatedData);
      res.status(201).json(guide);
    } catch (error) {
      console.error("Error creating user guide:", error);
      res.status(400).json({ message: "Invalid user guide data" });
    }
  });

  // Track download for a specific guide
  app.post("/api/repair-guides/:id/download", async (req, res) => {
    try {
      const guide = await storage.getRepairGuide(req.params.id);
      if (!guide) {
        return res.status(404).json({ message: "Repair guide not found" });
      }
      // Increment download count when guide is downloaded
      await storage.updateDownloadCount(req.params.id);
      res.json({ success: true, message: "Download tracked" });
    } catch (error) {
      res.status(500).json({ message: "Failed to track download" });
    }
  });

  // Version endpoint
  app.get("/api/version", async (req, res) => {
    try {
      const versionInfo = {
        version: "1.0.0",
        name: "JCR Guide Pro",
        build: "2025.08.18",
        release: "Major Release"
      };
      res.json(versionInfo);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch version info" });
    }
  });

  // Admin routes
  app.get("/api/admin/users", requireAdmin, async (req, res) => {
    try {
      // This would need a getAllUsers method in storage - for now return basic info
      res.json({ message: "Admin access confirmed", adminEmail: req.adminUser?.email });
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch admin data" });
    }
  });

  app.get("/api/admin/stats", requireAdmin, async (req, res) => {
    try {
      const guides = await storage.getRepairGuides();
      const totalViews = guides.reduce((sum, guide) => sum + (guide.viewCount || 0), 0);
      const totalDownloads = guides.reduce((sum, guide) => sum + (guide.downloadCount || 0), 0);

      res.json({
        totalGuides: guides.length,
        totalViews,
        totalDownloads,
        adminUser: req.adminUser?.email
      });
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch admin stats" });
    }
  });

  // Bulk download endpoint
  app.post("/api/download/bulk", async (req, res) => {
    try {
      const { type, filters } = req.body;
      let data: any[] = [];

      switch (type) {
        case 'repair-guides':
          data = await storage.getRepairGuides(filters || {});
          break;
        case 'troubleshooting-flows':
          data = await storage.getTroubleshootingFlows();
          break;
        case 'device-components':
          data = await storage.getDeviceComponents();
          break;
        case 'complete':
          const [guides, flows, components] = await Promise.all([
            storage.getRepairGuides({}),
            storage.getTroubleshootingFlows(),
            storage.getDeviceComponents()
          ]);
          const exportData = {
            exportInfo: {
              title: 'JCR Guide Pro Complete Export',
              version: '1.0',
              exportedAt: new Date().toISOString(),
              totalItems: guides.length + flows.length + components.length
            },
            repairGuides: guides,
            troubleshootingFlows: flows,
            deviceComponents: components
          };
          data = exportData as any;
          break;
        default:
          return res.status(400).json({ message: "Invalid download type" });
      }

      res.json({
        success: true,
        data,
        count: Array.isArray(data) ? data.length : Object.keys(data).length - 1,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error("Bulk download error:", error);
      res.status(500).json({ message: "Failed to prepare bulk download" });
    }
  });

  app.patch("/api/repair-guides/:id/bookmark", async (req, res) => {
    try {
      const guide = await storage.toggleBookmark(req.params.id);
      if (!guide) {
        return res.status(404).json({ message: "Repair guide not found" });
      }
      res.json(guide);
    } catch (error) {
      res.status(500).json({ message: "Failed to toggle bookmark" });
    }
  });

  // Troubleshooting Flows
  app.get("/api/troubleshooting-flows", async (req, res) => {
    try {
      const flows = await storage.getTroubleshootingFlows();
      res.json(flows);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch troubleshooting flows" });
    }
  });

  app.get("/api/troubleshooting-flows/:id", async (req, res) => {
    try {
      const flow = await storage.getTroubleshootingFlow(req.params.id);
      if (!flow) {
        return res.status(404).json({ message: "Troubleshooting flow not found" });
      }
      res.json(flow);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch troubleshooting flow" });
    }
  });

  app.post("/api/troubleshooting-flows", async (req, res) => {
    try {
      const validatedData = insertTroubleshootingFlowSchema.parse(req.body);
      const flow = await storage.createTroubleshootingFlow(validatedData);
      res.status(201).json(flow);
    } catch (error) {
      res.status(400).json({ message: "Invalid troubleshooting flow data" });
    }
  });

  // Device Components
  app.get("/api/device-components", async (req, res) => {
    try {
      const { deviceType } = req.query;
      const components = await storage.getDeviceComponents(deviceType as string);
      res.json(components);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch device components" });
    }
  });

  app.get("/api/device-components/:id", async (req, res) => {
    try {
      const component = await storage.getDeviceComponent(req.params.id);
      if (!component) {
        return res.status(404).json({ message: "Device component not found" });
      }
      res.json(component);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch device component" });
    }
  });

  app.post("/api/device-components", async (req, res) => {
    try {
      const validatedData = insertDeviceComponentSchema.parse(req.body);
      const component = await storage.createDeviceComponent(validatedData);
      res.status(201).json(component);
    } catch (error) {
      res.status(400).json({ message: "Invalid device component data" });
    }
  });

  // Device Brands routes
  app.get("/api/device-brands", async (req, res) => {
    try {
      const { deviceType } = req.query;
      const brands = await storage.getDeviceBrands(deviceType as string);
      res.json(brands);
    } catch (error) {
      console.error("Error fetching device brands:", error);
      res.status(500).json({ message: "Failed to fetch device brands" });
    }
  });

  // Device Models routes
  app.get("/api/device-models", async (req, res) => {
    try {
      const { brandId, deviceType, search } = req.query;

      if (search) {
        const models = await storage.searchDeviceModels(search as string, deviceType as string);
        res.json(models);
      } else {
        const models = await storage.getDeviceModels(brandId as string, deviceType as string);
        res.json(models);
      }
    } catch (error) {
      console.error("Error fetching device models:", error);
      res.status(500).json({ message: "Failed to fetch device models" });
    }
  });

  app.get("/api/device-models/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const model = await storage.getDeviceModel(id);
      if (!model) {
        return res.status(404).json({ message: "Device model not found" });
      }
      res.json(model);
    } catch (error) {
      console.error("Error fetching device model:", error);
      res.status(500).json({ message: "Failed to fetch device model" });
    }
  });

  app.get("/api/brands/:brandId/models", async (req, res) => {
    try {
      const { brandId } = req.params;
      const models = await storage.getModelsByBrand(brandId);
      res.json(models);
    } catch (error) {
      console.error("Error fetching models by brand:", error);
      res.status(500).json({ message: "Failed to fetch models by brand" });
    }
  });

  // Guide Compatibility routes
  app.get("/api/models/:modelId/guides", async (req, res) => {
    try {
      const { modelId } = req.params;
      const guides = await storage.getCompatibleGuides(modelId);
      res.json(guides);
    } catch (error) {
      console.error("Error fetching compatible guides:", error);
      res.status(500).json({ message: "Failed to fetch compatible guides" });
    }
  });

  app.get("/api/guides/:guideId/models", async (req, res) => {
    try {
      const { guideId } = req.params;
      const models = await storage.getModelCompatibility(guideId);
      res.json(models);
    } catch (error) {
      console.error("Error fetching model compatibility:", error);
      res.status(500).json({ message: "Failed to fetch model compatibility" });
    }
  });

  const httpServer = createServer(app);
  return httpServer;
}

server/storage.ts.content:
import {
  repairGuides,
  troubleshootingFlows,
  deviceComponents,
  users,
  favorites,
  deviceBrands,
  deviceModels,
  guideCompatibility,
  type RepairGuide,
  type InsertRepairGuide,
  type TroubleshootingFlow,
  type InsertTroubleshootingFlow,
  type DeviceComponent,
  type InsertDeviceComponent,
  type User,
  type UpsertUser,
  type Favorite,
  type InsertFavorite,
  type DeviceBrand,
  type InsertDeviceBrand,
  type DeviceModel,
  type InsertDeviceModel,
  type GuideCompatibility,
  type InsertGuideCompatibility,
} from "@shared/schema";
import { db } from "./db";
import { eq, and, like, or, sql } from "drizzle-orm";

export interface IStorage {
  // User operations (mandatory for Replit Auth)
  getUser(id: string): Promise<User | undefined>;
  upsertUser(user: UpsertUser): Promise<User>;

  // Favorites operations
  getUserFavorites(userId: string): Promise<Favorite[]>;
  addToFavorites(userId: string, favorite: InsertFavorite): Promise<Favorite>;
  removeFromFavorites(userId: string, itemId: string, itemType: string): Promise<void>;
  isFavorited(userId: string, itemId: string, itemType: string): Promise<boolean>;

  // Repair Guides
  getRepairGuides(filters?: { deviceType?: string; category?: string; difficulty?: string }): Promise<RepairGuide[]>;
  getRepairGuide(id: string): Promise<RepairGuide | undefined>;
  createRepairGuide(guide: InsertRepairGuide): Promise<RepairGuide>;
  updateViewCount(id: string): Promise<void>;
  updateDownloadCount(id: string): Promise<void>;
  toggleBookmark(id: string): Promise<RepairGuide | undefined>;
  searchRepairGuides(query: string): Promise<RepairGuide[]>;

  // Troubleshooting Flows
  getTroubleshootingFlows(): Promise<TroubleshootingFlow[]>;
  getTroubleshootingFlow(id: string): Promise<TroubleshootingFlow | undefined>;
  createTroubleshootingFlow(flow: InsertTroubleshootingFlow): Promise<TroubleshootingFlow>;

  // Device Components
  getDeviceComponents(deviceType?: string): Promise<DeviceComponent[]>;
  getDeviceComponent(id: string): Promise<DeviceComponent | undefined>;
  createDeviceComponent(component: InsertDeviceComponent): Promise<DeviceComponent>;

  // Device Brands and Models
  getDeviceBrands(deviceType?: string): Promise<DeviceBrand[]>;
  getDeviceModels(brandId?: string, deviceType?: string): Promise<DeviceModel[]>;
  getDeviceModel(id: string): Promise<DeviceModel | undefined>;
  getModelsByBrand(brandId: string): Promise<DeviceModel[]>;
  searchDeviceModels(query: string, deviceType?: string): Promise<DeviceModel[]>;

  // Guide Compatibility
  getCompatibleGuides(modelId: string): Promise<RepairGuide[]>;
  getModelCompatibility(guideId: string): Promise<DeviceModel[]>;

  // User guide creation
  createUserGuide(guide: InsertRepairGuide): Promise<RepairGuide>;
}

export class DatabaseStorage implements IStorage {
  // User operations (mandatory for Replit Auth)
  async getUser(id: string): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.id, id));
    return user;
  }

  async upsertUser(userData: UpsertUser): Promise<User> {
    const [user] = await db
      .insert(users)
      .values(userData)
      .onConflictDoUpdate({
        target: users.id,
        set: {
          ...userData,
          updatedAt: new Date(),
        },
      })
      .returning();
    return user;
  }

  // Favorites operations
  async getUserFavorites(userId: string): Promise<Favorite[]> {
    return await db.select().from(favorites).where(eq(favorites.userId, userId));
  }

  async addToFavorites(userId: string, favorite: InsertFavorite): Promise<Favorite> {
    const [newFavorite] = await db
      .insert(favorites)
      .values({ ...favorite, userId })
      .returning();
    return newFavorite;
  }

  async removeFromFavorites(userId: string, itemId: string, itemType: string): Promise<void> {
    await db
      .delete(favorites)
      .where(
        and(
          eq(favorites.userId, userId),
          eq(favorites.itemId, itemId),
          eq(favorites.itemType, itemType)
        )
      );
  }

  async isFavorited(userId: string, itemId: string, itemType: string): Promise<boolean> {
    const [favorite] = await db
      .select()
      .from(favorites)
      .where(
        and(
          eq(favorites.userId, userId),
          eq(favorites.itemId, itemId),
          eq(favorites.itemType, itemType)
        )
      );
    return !!favorite;
  }

  // Repair Guides operations
  async getRepairGuides(filters?: { deviceType?: string; category?: string; difficulty?: string }): Promise<RepairGuide[]> {
    let query = db.select().from(repairGuides);

    if (filters?.deviceType) {
      query = query.where(eq(repairGuides.deviceType, filters.deviceType));
    }
    if (filters?.category) {
      query = query.where(eq(repairGuides.category, filters.category));
    }
    if (filters?.difficulty) {
      query = query.where(eq(repairGuides.difficulty, filters.difficulty));
    }

    return await query;
  }

  async getRepairGuide(id: string): Promise<RepairGuide | undefined> {
    const [guide] = await db.select().from(repairGuides).where(eq(repairGuides.id, id));
    return guide;
  }

  async createRepairGuide(guide: InsertRepairGuide): Promise<RepairGuide> {
    const [newGuide] = await db.insert(repairGuides).values(guide).returning();
    return newGuide;
  }

  async updateViewCount(id: string): Promise<void> {
    await db
      .update(repairGuides)
      .set({ viewCount: sql`${repairGuides.viewCount} + 1` })
      .where(eq(repairGuides.id, id));
  }

  async updateDownloadCount(id: string): Promise<void> {
    await db
      .update(repairGuides)
      .set({ downloadCount: sql`${repairGuides.downloadCount} + 1` })
      .where(eq(repairGuides.id, id));
  }



  async toggleBookmark(id: string): Promise<RepairGuide | undefined> {
    const [guide] = await db
      .update(repairGuides)
      .set({ isBookmarked: sql`NOT ${repairGuides.isBookmarked}` })
      .where(eq(repairGuides.id, id))
      .returning();
    return guide;
  }

  async searchRepairGuides(query: string): Promise<RepairGuide[]> {
    const searchTerm = `%${query.toLowerCase()}%`;
    return await db
      .select()
      .from(repairGuides)
      .where(
        or(
          like(repairGuides.title, searchTerm),
          like(repairGuides.description, searchTerm),
          like(repairGuides.category, searchTerm)
        )
      );
  }

  // Troubleshooting Flows operations
  async getTroubleshootingFlows(): Promise<TroubleshootingFlow[]> {
    return await db.select().from(troubleshootingFlows);
  }

  async getTroubleshootingFlow(id: string): Promise<TroubleshootingFlow | undefined> {
    const [flow] = await db.select().from(troubleshootingFlows).where(eq(troubleshootingFlows.id, id));
    return flow;
  }

  async createTroubleshootingFlow(flow: InsertTroubleshootingFlow): Promise<TroubleshootingFlow> {
    const [newFlow] = await db.insert(troubleshootingFlows).values(flow).returning();
    return newFlow;
  }

  // Device Components operations
  async getDeviceComponents(deviceType?: string): Promise<DeviceComponent[]> {
    if (deviceType) {
      return await db.select().from(deviceComponents).where(eq(deviceComponents.deviceType, deviceType));
    }
    return await db.select().from(deviceComponents);
  }

  async getDeviceComponent(id: string): Promise<DeviceComponent | undefined> {
    const [component] = await db.select().from(deviceComponents).where(eq(deviceComponents.id, id));
    return component;
  }

  async createDeviceComponent(component: InsertDeviceComponent): Promise<DeviceComponent> {
    const [newComponent] = await db.insert(deviceComponents).values(component).returning();
    return newComponent;
  }

  // Device Brands and Models
  async getDeviceBrands(deviceType?: string): Promise<DeviceBrand[]> {
    const query = db.select().from(deviceBrands);
    if (deviceType) {
      return await query.where(eq(deviceBrands.deviceType, deviceType)).orderBy(sql`${deviceBrands.popularity} DESC`);
    }
    return await query.orderBy(sql`${deviceBrands.popularity} DESC`);
  }

  async getDeviceModels(brandId?: string, deviceType?: string): Promise<DeviceModel[]> {
    let query = db.select().from(deviceModels);

    if (brandId) {
      query = query.where(eq(deviceModels.brandId, brandId));
    }

    return await query.orderBy(sql`${deviceModels.year} DESC, ${deviceModels.name} ASC`);
  }

  async getDeviceModel(id: string): Promise<DeviceModel | undefined> {
    const [model] = await db.select().from(deviceModels).where(eq(deviceModels.id, id));
    return model;
  }

  async getModelsByBrand(brandId: string): Promise<DeviceModel[]> {
    return await db.select()
      .from(deviceModels)
      .where(eq(deviceModels.brandId, brandId))
      .orderBy(sql`${deviceModels.year} DESC, ${deviceModels.name} ASC`);
  }

  async searchDeviceModels(query: string, deviceType?: string): Promise<DeviceModel[]> {
    return await db.select()
      .from(deviceModels)
      .where(
        or(
          like(deviceModels.name, `%${query}%`),
          like(deviceModels.series, `%${query}%`)
        )
      )
      .orderBy(sql`${deviceModels.guideCount} DESC`);
  }

  // Guide Compatibility
  async getCompatibleGuides(modelId: string): Promise<RepairGuide[]> {
    return await db.select()
      .from(repairGuides)
      .innerJoin(guideCompatibility, eq(repairGuides.id, guideCompatibility.guideId))
      .where(
        and(
          eq(guideCompatibility.modelId, modelId),
          eq(guideCompatibility.compatibility, 'compatible')
        )
      )
      .orderBy(sql`${repairGuides.viewCount} DESC`);
  }

  async getModelCompatibility(guideId: string): Promise<DeviceModel[]> {
    return await db.select()
      .from(deviceModels)
      .innerJoin(guideCompatibility, eq(deviceModels.id, guideCompatibility.modelId))
      .where(eq(guideCompatibility.guideId, guideId))
      .orderBy(sql`${deviceModels.name} ASC`);
  }

  async createUserGuide(guide: InsertRepairGuide): Promise<RepairGuide> {
    const [createdGuide] = await db
      .insert(repairGuides)
      .values(guide)
      .returning();
    return createdGuide;
  }
}

export const storage = new DatabaseStorage();

