  namespace Express {
    interface Request {
      adminUser?: {
        id: string;
        email: string | null;
        firstName: string | null;
        lastName: string | null;
        profileImageUrl: string | null;
        role: string | null;
        createdAt: Date | null;
        updatedAt: Date | null;
      };
    }
  }
}

