import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import Header from "@/components/layout/header";
import Footer from "@/components/layout/footer";
import DeviceSelector from "@/components/repair/device-selector";
import CategoryGrid from "@/components/repair/category-grid";
import GuideCard from "@/components/repair/guide-card";
import PartsIdentification from "@/components/repair/parts-identification";
import TroubleshootingFlowchart from "@/components/repair/troubleshooting-flowchart";
import SoftwareLinks from "@/components/repair/software-links";
import FloatingActionButton from "@/components/repair/floating-action-button";
import GuideDetailModal from "@/components/repair/guide-detail-modal";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { RepairGuide } from "@shared/schema";

export default function Home() {
  const [selectedDeviceType, setSelectedDeviceType] = useState<"laptop" | "desktop">("laptop");
  const [selectedCategory, setSelectedCategory] = useState<string>("");
  const [sortOption, setSortOption] = useState<string>("popular");
  const [selectedGuideId, setSelectedGuideId] = useState<string | null>(null);

  const { data: repairGuides = [], isLoading } = useQuery<RepairGuide[]>({
    queryKey: ["/api/repair-guides", selectedDeviceType, selectedCategory],
    queryFn: () => {
      const params = new URLSearchParams();
      if (selectedDeviceType) params.append('deviceType', selectedDeviceType);
      if (selectedCategory) params.append('category', selectedCategory);
      return fetch(`/api/repair-guides?${params}`).then(res => res.json());
    },
  });

  const sortedGuides = [...repairGuides].sort((a, b) => {
    switch (sortOption) {
      case "difficulty":
        const difficultyOrder = { easy: 1, medium: 2, hard: 3 };
        return difficultyOrder[a.difficulty as keyof typeof difficultyOrder] - difficultyOrder[b.difficulty as keyof typeof difficultyOrder];
      case "time":
        return a.estimatedTime.localeCompare(b.estimatedTime);
      case "popular":
      default:
        return (b.viewCount || 0) - (a.viewCount || 0);
    }
  });

  const filteredGuides = selectedCategory 
    ? sortedGuides.filter(guide => guide.category === selectedCategory)
    : sortedGuides;

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 amoled:bg-black">
      <Header />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {/* Device Type Selection */}
        <section className="mb-8">
          <DeviceSelector 
            selectedType={selectedDeviceType} 
            onTypeChange={setSelectedDeviceType} 
          />
        </section>

        {/* Category Grid */}
        <section className="mb-8">
          <CategoryGrid 
            selectedCategory={selectedCategory}
            onCategoryChange={setSelectedCategory}
            deviceType={selectedDeviceType}
          />
        </section>

        {/* Repair Guides List */}
        <section className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-medium text-gray-900 dark:text-white">Popular Repair Guides</h2>
            <div className="flex items-center space-x-4">
              <Select value={sortOption} onValueChange={setSortOption}>
                <SelectTrigger className="w-48">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="popular">Most Popular</SelectItem>
                  <SelectItem value="difficulty">Difficulty: Easy to Hard</SelectItem>
                  <SelectItem value="time">Estimated Time</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {isLoading ? (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="bg-white dark:bg-gray-800 rounded-xl shadow-material animate-pulse">
                  <div className="h-48 bg-gray-200 rounded-t-xl"></div>
                  <div className="p-6 space-y-3">
                    <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                    <div className="h-3 bg-gray-200 rounded w-full"></div>
                    <div className="h-3 bg-gray-200 rounded w-5/6"></div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {filteredGuides.map(guide => (
                <GuideCard 
                  key={guide.id} 
                  guide={guide} 
                  onViewGuide={() => setSelectedGuideId(guide.id)}
                />
              ))}
            </div>
          )}

          {!isLoading && filteredGuides.length === 0 && (
            <div className="text-center py-12">
              <div className="text-gray-400 mb-4">
                <i className="material-icons text-6xl">search_off</i>
              </div>
              <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">No guides found</h3>
              <p className="text-gray-600 dark:text-gray-300">Try adjusting your filters or selecting a different device type.</p>
            </div>
          )}
