import React from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { useToast } from "@/hooks/use-toast";
import { useOfflineMode } from "@/hooks/useOfflineMode";
import { formatStorageSize } from "@/lib/offline-storage";
import { 
  Download, 
  Upload, 
  Wifi, 
  WifiOff, 
  HardDrive, 
  Trash2, 
  RefreshCw,
  CheckCircle,
  AlertCircle,
  Clock
} from "lucide-react";

export default function OfflineSettings() {
  const { toast } = useToast();
  const {
    isOfflineSupported,
    isOfflineModeEnabled,
    isCurrentlyOnline,
    lastSyncTime,
    storageInfo,
    enableOfflineMode,
    disableOfflineMode,
    forceSync,
    getOfflineData,
  } = useOfflineMode();

  const handleEnableOffline = async () => {
    const success = await enableOfflineMode();
    if (success) {
      toast({
        title: "Offline Mode Enabled",
        description: "Repair guides have been cached for offline use.",
      });
    } else {
      toast({
        title: "Failed to Enable Offline Mode",
        description: "Please check your connection and try again.",
        variant: "destructive",
      });
    }
  };

  const handleDisableOffline = () => {
    disableOfflineMode();
    toast({
      title: "Offline Mode Disabled",
      description: "Offline data will no longer be used.",
    });
  };

  const handleForceSync = async () => {
    if (!isCurrentlyOnline) {
      toast({
        title: "No Internet Connection",
        description: "Connect to the internet to sync data.",
        variant: "destructive",
      });
      return;
    }

    const success = await forceSync();
    if (success) {
      toast({
        title: "Sync Complete",
        description: "All data has been synchronized.",
      });
    } else {
      toast({
        title: "Sync Failed",
        description: "Please check your connection and try again.",
        variant: "destructive",
      });
    }
  };

  const offlineData = getOfflineData();

  if (!isOfflineSupported) {
    return (
      <div className="container mx-auto py-8 px-4">
        <div className="max-w-4xl mx-auto">
          <h1 className="text-3xl font-bold mb-6">Offline Mode</h1>

          <Card>
            <CardContent className="p-8 text-center">
              <AlertCircle className="h-16 w-16 mx-auto mb-4 text-gray-400" />
              <h2 className="text-xl font-semibold mb-2">Offline Mode Not Supported</h2>
              <p className="text-muted-foreground">
                Your browser doesn't support the features required for offline mode.
                Please use a modern browser with localStorage support.
              </p>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="mb-6">
          <h1 className="text-3xl font-bold mb-2">Offline Mode Settings</h1>
          <p className="text-muted-foreground">
            Configure offline access to repair guides for when you don't have internet connectivity.
          </p>
        </div>

        {/* Connection Status */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              {isCurrentlyOnline ? (
                <>
                  <Wifi className="h-5 w-5 text-green-600" />
                  Online
                </>
              ) : (
                <>
                  <WifiOff className="h-5 w-5 text-red-600" />
                  Offline
                </>
              )}
            </CardTitle>
            <CardDescription>
              {isCurrentlyOnline 
                ? "You're connected to the internet and can access all features."
                : "You're offline. Only cached content is available."
              }
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-4">
              <Badge variant={isCurrentlyOnline ? "default" : "destructive"}>
                {isCurrentlyOnline ? "Connected" : "Disconnected"}
              </Badge>
              {lastSyncTime && (
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Clock className="h-4 w-4" />
                  Last sync: {lastSyncTime.toLocaleString()}
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Offline Mode Control */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Download className="h-5 w-5" />
              Offline Mode
            </CardTitle>
            <CardDescription>
              Enable offline mode to cache repair guides for use without internet connectivity.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex items-center justify-between mb-4">
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-medium">Status:</span>
                  <Badge variant={isOfflineModeEnabled ? "default" : "secondary"}>
                    {isOfflineModeEnabled ? "Enabled" : "Disabled"}
                  </Badge>
                </div>
                <p className="text-sm text-muted-foreground">
                  {isOfflineModeEnabled 
                    ? "Guides are cached and available offline"
                    : "Offline access is not enabled"
                  }
                </p>
              </div>
              <div className="flex gap-2">
                {isOfflineModeEnabled ? (
                  <Button onClick={handleDisableOffline} variant="outline">
                    Disable Offline Mode
                  </Button>
                ) : (
                  <Button 
                    onClick={handleEnableOffline}
                    disabled={!isCurrentlyOnline}
                  >
                    <Download className="h-4 w-4 mr-2" />
                    Enable Offline Mode
                  </Button>
                )}

                {isOfflineModeEnabled && (
                  <Button 
                    onClick={handleForceSync}
                    disabled={!isCurrentlyOnline}
                    variant="outline"
                  >
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Sync Now
                  </Button>
                )}
              </div>
            </div>

            {!isCurrentlyOnline && !isOfflineModeEnabled && (
              <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg">
                <div className="flex items-center gap-2 text-amber-800 dark:text-amber-200">
                  <AlertCircle className="h-4 w-4" />
                  <span className="text-sm font-medium">
                    You're offline and don't have cached content. Connect to the internet to enable offline mode.
                  </span>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Storage Information */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <HardDrive className="h-5 w-5" />
              Storage Usage
            </CardTitle>
            <CardDescription>
              Local storage usage for offline content.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div>
                <div className="flex justify-between items-center mb-2">
                  <span className="text-sm font-medium">Storage Used</span>
                  <span className="text-sm text-muted-foreground">
                    {formatStorageSize(storageInfo.used)} / {formatStorageSize(storageInfo.available)}
                  </span>
                </div>
                <Progress value={storageInfo.percentage} className="h-2" />
                <p className="text-xs text-muted-foreground mt-1">
                  {storageInfo.percentage.toFixed(1)}% of available storage used
                </p>
              </div>

              {storageInfo.percentage > 80 && (
                <div className="p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg">
                  <div className="flex items-center gap-2 text-amber-800 dark:text-amber-200">
                    <AlertCircle className="h-4 w-4" />
                    <span className="text-sm">
                      Storage is getting full. Consider clearing offline data to free up space.
                    </span>
                  </div>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Cached Content Summary */}
        {isOfflineModeEnabled && (
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <CheckCircle className="h-5 w-5" />
                Cached Content
              </CardTitle>
              <CardDescription>
                Content available for offline use.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="text-center p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                  <div className="text-2xl font-bold text-blue-600">{offlineData.guides.length}</div>
                  <div className="text-sm text-muted-foreground">Repair Guides</div>
                </div>

                <div className="text-center p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                  <div className="text-2xl font-bold text-green-600">{offlineData.flows.length}</div>
                  <div className="text-sm text-muted-foreground">Troubleshooting Flows</div>
                </div>

                <div className="text-center p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                  <div className="text-2xl font-bold text-purple-600">{offlineData.components.length}</div>
                  <div className="text-sm text-muted-foreground">Device Components</div>
                </div>
              </div>

              {offlineData.userGuides.length > 0 && (
                <div className="mt-4 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                  <div className="flex items-center gap-2 text-blue-800 dark:text-blue-200 mb-2">
                    <Upload className="h-4 w-4" />
                    <span className="text-sm font-medium">
                      {offlineData.userGuides.length} user guide(s) pending sync
                    </span>
                  </div>
                  <p className="text-xs text-blue-700 dark:text-blue-300">
                    These guides will be uploaded to the server when you're back online.
                  </p>
                </div>
              )}
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

