              onClick={() => setLocation("/")}
              className="flex items-center space-x-2 hover:opacity-80 transition-opacity"
            >
              <i className="material-icons text-primary-700 text-2xl">build</i>
              <h1 className="text-xl font-medium text-gray-900 dark:text-white amoled:text-white">JCR Guide Pro</h1>
            </button>

            {/* Navigation */}
            <nav className="hidden md:flex items-center space-x-6 ml-8">
              <button
                onClick={() => setLocation("/")}
                className="text-sm text-gray-600 dark:text-gray-300 hover:text-primary-700 dark:hover:text-primary-400 transition-colors"
              >
                Guides
              </button>

              {/* Tools & Content Dropdown */}
              <DropdownMenu>
                <DropdownMenuTrigger className="flex items-center gap-1 text-sm text-gray-600 dark:text-gray-300 hover:text-primary-700 dark:hover:text-primary-400 transition-colors">
