import { useQuery } from "@tanstack/react-query";
import type { RepairGuide } from "@shared/schema";

interface CategoryGridProps {
  selectedCategory: string;
  onCategoryChange: (category: string) => void;
  deviceType: string;
}

export default function CategoryGrid({ selectedCategory, onCategoryChange, deviceType }: CategoryGridProps) {
  const { data: allGuides = [] } = useQuery<RepairGuide[]>({
    queryKey: ["/api/repair-guides", deviceType],
    queryFn: () => {
      const params = new URLSearchParams();
      if (deviceType) params.append('deviceType', deviceType);
      return fetch(`/api/repair-guides?${params}`).then(res => res.json());
    },
  });

  const categories = [
    {
      id: "hardware",
      name: "Hardware",
      description: "Component repairs, replacements, and installations",
      icon: "memory",
      color: "text-primary-700",
      bgColor: "bg-primary-50",
    },
    {
      id: "software",
      name: "Software",
      description: "OS troubleshooting, driver issues, and system recovery",
      icon: "code",
      color: "text-success-600",
      bgColor: "bg-success-50",
    },
    {
      id: "cleaning",
      name: "Cleaning",
      description: "Dust removal, thermal paste, and maintenance",
      icon: "cleaning_services",
      color: "text-warning-700",
      bgColor: "bg-warning-50",
    },
    {
      id: "upgrades",
      name: "Upgrades",
      description: "RAM, storage, and performance improvements",
      icon: "upgrade",
      color: "text-purple-600",
      bgColor: "bg-purple-50",
    },
  ];

  const getCategoryCount = (categoryId: string) => {
    return allGuides.filter(guide => guide.category === categoryId).length;
  };

  return (
    <section>
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-lg font-medium text-gray-900 dark:text-white">Repair Categories</h2>
        {selectedCategory && (
          <button
            onClick={() => onCategoryChange("")}
            className="text-sm text-primary-700 hover:text-primary-900 transition-colors"
          >
            Clear filter
          </button>
        )}
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {categories.map((category) => (
          <button
            key={category.id}
            onClick={() => onCategoryChange(selectedCategory === category.id ? "" : category.id)}
            className={`bg-white dark:bg-gray-800 rounded-xl shadow-material p-6 hover:shadow-material-lg transition-all cursor-pointer text-left ${
              selectedCategory === category.id ? "ring-2 ring-primary ring-offset-2" : ""
            }`}
          >
            <div className="flex items-center space-x-3 mb-3">
              <i className={`material-icons ${category.color} text-2xl`}>{category.icon}</i>
              <h3 className="font-medium text-gray-900 dark:text-white">{category.name}</h3>
            </div>
            <p className="text-sm text-gray-600 dark:text-gray-300 mb-2">{category.description}</p>
            <span className={`inline-block px-2 py-1 ${category.bgColor} ${category.color} text-xs rounded-full`}>
              {getCategoryCount(category.id)} guides
            </span>
          </button>
        ))}
      </div>
    </section>
  );
}

