import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { DownloadModal } from "@/components/ui/download-modal";
import { apiRequest } from "@/lib/queryClient";
import { Download } from "lucide-react";
import type { RepairGuide } from "@shared/schema";

interface GuideCardProps {
  guide: RepairGuide;
  onViewGuide: () => void;
}

export default function GuideCard({ guide, onViewGuide }: GuideCardProps) {
  const queryClient = useQueryClient();
  const [showDownloadModal, setShowDownloadModal] = useState(false);

  const bookmarkMutation = useMutation({
    mutationFn: () => apiRequest("PATCH", `/api/repair-guides/${guide.id}/bookmark`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/repair-guides"] });
    },
  });

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case "easy":
        return "bg-success-50 text-success-600";
      case "medium":
        return "bg-warning-50 text-warning-700";
      case "hard":
        return "bg-danger-50 text-danger-700";
      default:
        return "bg-gray-50 text-gray-600";
    }
  };

  const formatViewCount = (count: number) => {
    if (count >= 1000) {
      return `${(count / 1000).toFixed(1)}k`;
    }
    return count.toString();
  };

  return (
    <div className="bg-white dark:bg-gray-800 amoled:bg-black rounded-xl shadow-material hover:shadow-material-lg transition-shadow">
      <img
        src={guide.imageUrl}
        alt={guide.title}
        className="w-full h-48 object-cover rounded-t-xl"
      />

      <div className="p-6">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center space-x-2">
            <span className={`inline-block px-2 py-1 text-xs font-medium rounded-full ${getDifficultyColor(guide.difficulty)}`}>
              {guide.difficulty.toUpperCase()}
            </span>
            <span className="inline-block px-2 py-1 bg-gray-100 text-gray-600 text-xs rounded-full">
              {guide.estimatedTime}
            </span>
          </div>
          <Button
            variant="ghost"
            size="icon"
            onClick={(e) => {
              e.stopPropagation();
              bookmarkMutation.mutate();
            }}
            disabled={bookmarkMutation.isPending}
            className="p-1 text-gray-400 hover:text-primary-700 transition-colors"
          >
            <i className={`material-icons text-sm ${guide.isBookmarked ? "text-primary-700" : ""}`}>
              {guide.isBookmarked ? "bookmark" : "bookmark_border"}
            </i>
          </Button>
        </div>

        <h3 className="font-medium text-gray-900 dark:text-white amoled:text-white mb-2">{guide.title}</h3>
        <p className="text-sm text-gray-600 dark:text-gray-300 amoled:text-gray-300 mb-4 line-clamp-2">{guide.description}</p>

        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4 text-sm text-gray-500">
            <span className="flex items-center space-x-1">
              <i className="material-icons text-sm">build</i>
              <span>{guide.toolsRequired.length} tools</span>
            </span>
            <span className="flex items-center space-x-1">
              <i className="material-icons text-sm">visibility</i>
              <span>{formatViewCount(guide.viewCount || 0)} views</span>
            </span>
            <span className="flex items-center space-x-1">
              <i className="material-icons text-sm">download</i>
              <span>{formatViewCount(guide.downloadCount || 0)} downloads</span>
            </span>
          </div>
          <div className="flex items-center space-x-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                setShowDownloadModal(true);
              }}
              className="text-gray-500 hover:text-primary-700 p-1"
            >
              <Download className="h-4 w-4" />
            </Button>
            <Button
              onClick={onViewGuide}
              className="px-4 py-2 bg-primary-700 text-white text-sm rounded-lg hover:bg-primary-900 transition-colors"
            >
              View Guide
            </Button>
          </div>
        </div>
      </div>

      <DownloadModal
        open={showDownloadModal}
        onOpenChange={setShowDownloadModal}
        guide={guide}
      />
    </div>
  );
}

